try {
  if (!$input.all().length) {
    return [{
      json: {
        valid: true,
        message: "Initial trigger - proceeding to load preferences"
      }
    }];
  }

  const items = $input.all();
  if (!items.length) {
    return [{
      json: {
        valid: false,
        error: "No data received from trigger"
      }
    }];
  }

  return [{
    json: {
      valid: true,
      message: "Validation passed"
    }
  }];

} catch (error) {
  return [{
    json: {
      valid: false,
      error: `Setup validation failed: ${error.message}`
    }
  }];
}

try {
  const input = $input.first().json;

  // Parse match datetime
  const matchDateStr = input['Match Datetime'];
  if (!matchDateStr) {
    return [{
      json: {
        shouldPoll: false,
        reason: "No Match Datetime set. Please add match time to Google Sheet."
      }
    }];
  }

  const matchTime = new Date(matchDateStr);
  const now = new Date();

  // Calculate hours difference
  const hoursDiff = (matchTime - now) / (1000 * 60 * 60);


  const shouldPoll = hoursDiff >= -2 && hoursDiff <= 2;

  if (!shouldPoll) {
    return [{
      json: {
        shouldPoll: false,
        reason: `Match window not active. Match is ${Math.abs(hoursDiff).toFixed(1)}h ${hoursDiff > 0 ? 'in future' : 'in past'}`,
        nextCheck: matchTime.toISOString()
      }
    }];
  }

  return [{
    json: {
      shouldPoll: true,
      ...input
    }
  }];

} catch (error) {
  return [{
    json: {
      shouldPoll: false,
      error: `Match timing check failed: ${error.message}`
    }
  }];
}

try {
  const apiResponse = $input.item.json;
  const response = apiResponse.response;

  // Validate API response
  if (!response || !Array.isArray(response) || response.length === 0) {
    return [];
  }

  const match = response[0];
  const events = match?.events || [];

  const userPrefsNode = $('Filter Active Users Only');
  if (!userPrefsNode || !userPrefsNode.first()) {
    throw new Error('Cannot find user preferences node');
  }

  const userPrefs = userPrefsNode.first().json;

  const userTeamId = parseInt(userPrefs['Team ID']);
  if (isNaN(userTeamId)) {
    throw new Error(`Invalid Team ID: ${userPrefs['Team ID']}`);
  }

  const goals = events.filter(event => {
    return event?.type === 'Goal' && 
           event?.team?.id === userTeamId &&
           event?.detail !== 'Missed Penalty';
  });

  const notifiedGoals = userPrefs['Last Notified Goals'] || '';
  const notifiedArray = notifiedGoals.split(',').filter(Boolean);

  const newGoals = goals.filter(goal => {
    const goalId = `${goal.time.elapsed}_${goal.player.id}`;
    return !notifiedArray.includes(goalId);
  });

  if (newGoals.length === 0) {
    return [];
  }

  const allNewGoalIds = newGoals.map(g => `${g.time.elapsed}_${g.player.id}`);
  const updatedNotifiedGoals = [...notifiedArray, ...allNewGoalIds].join(',');

  const opponent = match?.teams?.home?.id === userTeamId 
    ? match?.teams?.away?.name || 'Unknown' 
    : match?.teams?.home?.name || 'Unknown';

  return newGoals.map(goal => ({
    json: {
      goalId: `${goal.time.elapsed}_${goal.player.id}`,
      playerName: goal?.player?.name || 'Unknown Player',
      minute: goal?.time?.elapsed || '0',
      teamName: goal?.team?.name || userPrefs['Team ID'],
      matchScore: `${match?.goals?.home || 0}-${match?.goals?.away || 0}`,
      opponent: opponent,
      userEmail: userPrefs['User Email'],
      delaySeconds: parseInt(userPrefs['Delay Seconds']) || 45,
      streamingService: userPrefs['Streaming Service'] || 'Streaming',
      updatedNotifiedGoals: updatedNotifiedGoals,
      matchStatus: match?.fixture?.status?.short || 'UNKNOWN'
    }
  }));

} catch (error) {
  return [{
    json: {
      error: true,
      errorMessage: `Goal detection failed: ${error.message}`,
      timestamp: new Date().toISOString()
    }
  }];
}

