// ===== CHECK MATCH STATUS =====
// Runs in parallel with goal detection - prevents Empty Array Trap

try {
  const apiResponse = $input.item.json;
  const response = apiResponse.response;

  // Validate API response
  if (!response || !Array.isArray(response) || response.length === 0) {
    return [];  // No match data, skip gracefully
  }

  const match = response[0];
  const matchStatus = match?.fixture?.status?.short || 'UNKNOWN';

  // Get user email from the active user node
  const userPrefsNode = $('Filter Active Users Only');
  if (!userPrefsNode || !userPrefsNode.first()) {
    throw new Error('Cannot find user preferences node');
  }

  const userPrefs = userPrefsNode.first().json;
  const userEmail = userPrefs['User Email'];

  // Check if match is finished
  const finishedStatuses = ['FT', 'AET', 'PEN', 'CANC', 'ABD', 'AWD', 'PST', 'SUSP'];
  const isFinished = finishedStatuses.includes(matchStatus);

  return [{
    json: {
      isFinished,
      matchStatus,
      userEmail,
      timestamp: new Date().toISOString()
    }
  }];

} catch (error) {
  return [{
    json: {
      error: true,
      errorMessage: `Match status check failed: ${error.message}`
    }
  }];
}
